        this.explosionParticleEmitterSubModels = rw.ListNodeRef_deprec<CPlugParticleEmitterSubModel>(this.explosionParticleEmitterSubModels);

        if (v >= 1)
        {
            rw.Single(ref this.bulletExplosionBlowRadiusAttenuation);
