            if (v >= 2)
            {
                rw.Single(ref this.bulletImpactBouncingN);
                rw.Single(ref this.bulletImpactBouncingT);

                if (v >= 4)
                {
                    if (v <= 18)
                    {
                        rw.Boolean(ref this.u11);
                    }

                    rw.Single(ref this.bulletHomingDist);
                    rw.Single(ref this.bulletHomingAngularSpeed);
                    rw.Single(ref this.bulletHomingPeriod);

