                                        if (v >= 10)
                                        {
                                            rw.Boolean(ref this.bulletModifyFOV);

                                            if (v >= 11)
                                            {
                                                rw.Boolean(ref this.bulletExplosionOnAllPlayers);

                                                if (v >= 12)
                                                {
