                                                        rw.Single(ref this.bulletFlareExplosionRadius);

                                                        if (v >= 14)
                                                        {
                                                            rw.Id(ref this.bulletHomingSound);
                                                            rw.Single(ref this.bulletHomingSoundVolume);

                                                            if (v >= 15)
                                                            {
                                                                if (v <= 18)
                                                                {
                                                                    rw.Boolean(ref this.u14);
                                                                }

                                                                rw.Single(ref this.bulletGuidedAngularSpeed);

                                                                if (v >= 16)
